<?php
/**
 * NEX - 47 CATALYS'S - Admin Secure Login Portal
 */

session_start();
if (file_exists(__DIR__ . '/../api/config.php')) { require_once __DIR__ . '/../api/config.php'; }
if (!function_exists('getDBConnection')) { function getDBConnection() { return null; } }

// Direct login display - no redirect loops

$error = '';
$success = '';

if (isset($_GET['logout'])) {
    $success = 'You have been successfully logged out.';
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    unset($_SESSION['admin_logged_in'], $_SESSION['admin_id'], $_SESSION['admin_name']);

    $email = trim($_POST['email'] ?? '');
    $password = trim($_POST['admin_pass_key'] ?? $_POST['password'] ?? '');

    if (empty($email) || empty($password)) {
        $error = 'Please enter both email/username and password.';
    } else {
        $valid = false;
        $adminUser = null;

        try {
            $pdo = getDBConnection();

            if ($pdo !== null) {
                $stmt = $pdo->prepare("SELECT * FROM `admins` WHERE `email` = :email OR `name` = :name LIMIT 1");

                $stmt->execute([':email' => $email, ':name' => $email]);
                $admin = $stmt->fetch();

                if ($admin && password_verify($password, $admin['password'])) {
                    $valid = true;
                    $adminUser = $admin;
                    try {
                        $pdo->prepare("UPDATE `admins` SET `last_login` = NOW() WHERE `id` = ?")->execute([$admin["id"]]);
                    } catch (Exception $ex) {}
                }
            }
        } catch (Exception $e) {}

        // Master Direct Fallback for samsparrow
        if (!$valid) {
            if (($email === 'admin@nex47.com' || $email === 'admin') && ($password === 'samsparrow')) {
                $valid = true;
                $adminUser = [
                    'id' => 1,
                    'name' => 'NEX-47 SuperAdmin',
                    'email' => 'admin@nex47.com',
                    'role' => 'superadmin'
                ];
            }
        }

        if ($valid && $adminUser) {
            $_SESSION['admin_logged_in'] = true;
            $_SESSION['admin_id'] = $adminUser['id'];
            $_SESSION['admin_name'] = $adminUser['name'];
            $_SESSION['admin_email'] = $adminUser['email'];
            $_SESSION['admin_role'] = $adminUser['role'] ?? 'superadmin';

            header('Location: /admin/index.php');
            exit;
        } else {
            $error = 'Access Denied: Incorrect password or username.';
        }
    }
}
